<script setup>
import {computed,ref,watch} from 'vue'
import {useDecisionResearch} from './useDecisionResearch.js'
import DecisionCitation from './DecisionCitation.vue'
import VersionComparison from './VersionComparison.vue'
import ResearchDataCharts from './ResearchDataCharts.vue'
import {candidateChartBlocks} from '../utils/decisionChartOptions.js'
const props=defineProps({id:String})
const developer=new URLSearchParams(location.search).get('developer')==='1'
const {state,history,error,submitting,loading,start,active,action,load,refresh}=useDecisionResearch(props.id,{navigate:rid=>{location.hash='#/candidates/'+rid}})
const months=ref(3),citation=ref(null),industry=ref(new URLSearchParams(location.search).get('industry')==='集成电路制造'?'集成电路制造':'半导体设备')
watch(()=>state.value?.request,value=>{if(value){industry.value=value.entity;months.value=value.horizon_months}})
const data=computed(()=>state.value?.data?.report?.stage==='P5'?state.value.data:null)
const opinions=computed(()=>data.value?.report.candidates || [])
const records=computed(()=>history.value.filter(r=>(developer||r.status==='COMPLETED')&&(r.page==='candidates'||r.title?.endsWith(' · 候选研究'))))
const member=id=>data.value?.members.find(r=>r.security_id===id)
const stance=value=>({PRIORITIZE_RESEARCH:'优先研究',WAIT_FOR_CONFIRMATION:'等待验证',RISK_FIRST:'先核查风险'}[value] || value)
const format=(value,scale=1)=>value==null?'—':(Number(value)/scale).toLocaleString('zh-CN',{maximumFractionDigits:2})
const generate=()=>start({entity:industry.value,scope:'industry',research_mode:'candidates',question:industry.value+'未来几个月哪些公司值得优先研究，为什么选它而没选同行？比较经营、资金与估值约束，保留反证和验证条件。',horizon_months:Number(months.value),budget_profile:{max_candidates:3}})
function scrollCandidate(id){document.getElementById('candidate-'+id)?.scrollIntoView({block:'start'})}
function compare(opinion){const peer=member(opinion.peer_ids[0]);if(!peer)return;sessionStorage.setItem('alpha-comparison-question',member(opinion.security_id).name+' vs '+peer.name);location.hash='#/compare'}
function deep(id){const url=new URL(location.href);url.searchParams.set('research','1');url.searchParams.set('entity',id);url.hash='#/decision';return url.pathname+url.search+url.hash}
function toggle(){const url=new URL(location.href);developer?url.searchParams.delete('developer'):url.searchParams.set('developer','1');return url.pathname+url.search+url.hash}
</script>
<template>
  <div class="page candidate-page">
    <section class="panel rep-section"><div class="section-heading"><h1>{{ industry }}，哪些公司值得先研究</h1><span v-if="developer" class="tag tag-warn">开发者视图</span></div><p class="prediction-lead">先看入选理由和同业差异，再核对反证与改变判断的条件。</p><form class="candidate-form" @submit.prevent="generate"><label>行业 <select v-model="industry"><option>半导体设备</option><option>集成电路制造</option></select></label><label>研究期限 <select v-model="months"><option :value="1">未来一个月</option><option :value="2">未来两个月</option><option :value="3">未来三个月</option></select></label><button class="btn btn-primary" :disabled="submitting||active(state)">{{ submitting?'正在提交…':active(state)?'正在研究…':data?'重新取数并另存研究':'开始候选研究' }}</button></form><p class="condition-note">范围为本次实际取得的{{ industry }}分类池。研究优先级与股价方向分别判断。</p><p v-if="loading&&!state" role="status">正在读取已保存研究…</p><p v-if="error" role="alert" class="error-text">{{ error }} <button class="btn" @click="load">重新读取</button></p></section>
    <section v-if="active(state)" class="panel rep-section" aria-live="polite"><h2>正在核对成分与公司依据</h2><p>{{ state.process.at(-1)?.detail }}</p><button class="btn" @click="action('cancel')" :disabled="submitting">停止研究</button></section>
    <section v-if="state&&['FAILED','INTERRUPTED','CANCELLED'].includes(state.status)" class="panel rep-section"><h2>本次候选研究尚未完成</h2><p>{{ developer?state.error:'本次行业资料或意见复核未完成，尚未发布候选。失败记录保留，可重试。' }}</p><button v-if="state.status!=='CANCELLED'" class="btn" @click="action('resume')" :disabled="submitting">继续未完成步骤</button></section>
    <template v-if="data">
      <p v-if="!data.report.prompt_version" class="notice">这是早期候选记录，估值措辞尚未按新版基准约束核对。原记录保留；请重新取数生成新版，贵或便宜的表述暂不作为判断依据。</p>
      <section class="panel rep-section candidate-overview"><h2>本次优先看这些公司</h2><p class="candidate-summary">{{ data.report.summary }}</p><p class="condition-note">资料截止 {{ new Date(data.report.cutoff_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}) }} · 成分 {{ data.coverage.universe_total }} 只 · 入选 {{ data.coverage.available }} 只 · 排除 {{ data.coverage.excluded }} 只 · 资料不足或未深研 {{ data.coverage.missing }} 只</p><p v-if="data.data_supply" class="condition-note">来源：Tushare · 申万2021沪深A股分类 · 行情截至 {{ data.data_supply.data_date }}。财务与估值为供应商转录，业务依据仍引用公司原文。</p><p v-if="!opinions.length" class="notice">本轮没有符合证据要求的候选。下方保留每家公司的缺项；不以固定名单填充。</p></section>
      <VersionComparison :id="id" page="candidates"/><section class="panel rep-section"><button class="btn" :disabled="submitting||active(state)" @click="refresh">更新本行业研究，另存版本</button><a class="btn" href="#/market">返回市场观察</a><a class="btn" :href="'/api/quant/decision/runs/'+id+'/export'" target="_blank" rel="noopener noreferrer">导出这次研究</a></section>
      <section v-if="opinions.length" class="panel rep-section"><h2>候选经营对照</h2><ResearchDataCharts :blocks="candidateChartBlocks(opinions.map(o=>member(o.security_id)))"/><p class="condition-note">合并报表 {{ data.members[0]?.period }}，供应商转录。规模不等于增长，现金流不代表净流入股市。</p><div class="candidate-verdicts"><a v-for="opinion in opinions" :key="opinion.security_id" :href="'#candidate-'+opinion.security_id" @click.prevent="scrollCandidate(opinion.security_id)"><strong>{{ member(opinion.security_id).name }}</strong><span>{{ opinion.outlook==='FAVORABLE'?'倾向看多':opinion.outlook==='UNFAVORABLE'?'倾向看空':stance(opinion.stance) }}</span></a></div></section>
      <article v-for="(opinion,index) in opinions" :key="opinion.security_id" :id="'candidate-'+opinion.security_id" class="panel rep-section candidate-card" :data-candidate-id="opinion.security_id">
        <div class="section-heading"><h2><span class="num candidate-number">0{{ index+1 }}</span>{{ member(opinion.security_id).name }}</h2><span class="tag">{{ stance(opinion.stance) }}</span></div><p class="condition-note">{{ member(opinion.security_id).leader_type==='LARGE_REPRESENTATIVE'?'池内大型代表公司，经营地位仍待独立证据核定':'研究候选，经营龙头地位尚未核定' }} · {{ member(opinion.security_id).group }}</p>
        <p class="candidate-summary">{{ opinion.summary }}</p><p>{{ opinion.reason }}</p><div class="candidate-reasons"><section><h3>为什么值得研究</h3><p v-for="item in opinion.supporting_reasons" :key="item">{{ item }}</p></section><section><h3>主要反对理由</h3><p v-for="item in opinion.opposing_reasons" :key="item">{{ item }}</p></section></div><p><b>资金是否配合</b> {{ opinion.funding }}</p><p v-if="member(opinion.security_id).funding_window" class="condition-note">融资窗口 {{ member(opinion.security_id).funding_window.start }} — {{ member(opinion.security_id).funding_window.end }}，为二十个交易日余额差；行情截至 {{ member(opinion.security_id).funding_window.price_end }}。融资与行情按各自公布日期展示。</p><p><b>估值约束</b> {{ opinion.valuation }}</p><p><b>与同行相比</b> {{ opinion.comparison }}</p><details><summary>什么事实会支持或推翻判断</summary><h3>接下来验证</h3><p v-for="item in opinion.verification_conditions" :key="item">{{ item }}</p><h3>重新评估的条件</h3><p v-for="item in opinion.invalidation_conditions" :key="item">{{ item }}</p></details><div class="candidate-citations"><button v-for="(id,n) in opinion.evidence_ids" :key="id" class="prediction-source" @click="citation=id">查看依据 {{ n+1 }} ↗</button><button v-for="(id,n) in opinion.counter_ids" :key="id" class="prediction-source" @click="citation=id">查看反证 {{ n+1 }} ↗</button></div><div class="candidate-actions"><a class="btn" :href="deep(opinion.security_id)">单股深研</a><button v-if="opinion.peer_ids.length" class="btn" @click="compare(opinion)">打开双股比较</button></div>
      </article>
      <section v-if="opinions.length" class="panel rep-section"><h2>同期间数据，放在一起看</h2><p class="condition-note">合并报表 {{ data.members[0]?.period }}，金额单位为亿元。产品结构不同，这些数值不能直接证明谁是经营龙头；供应商转录尚未逐项独立核验。</p><div class="candidate-table"><table class="data"><thead><tr><th>公司</th><th>营业收入</th><th>归母净利润</th><th>经营现金流净额</th><th>{{ data.data_supply?.data_source==='Tushare'?'过去十二月市盈率快照':'动态市盈率快照' }}</th><th>近二十日成交额中位数</th></tr></thead><tbody><tr v-for="opinion in opinions" :key="opinion.security_id"><th>{{ member(opinion.security_id).name }}</th><td>{{ format(member(opinion.security_id).metrics.TOTAL_OPERATE_INCOME,1e8) }}</td><td>{{ format(member(opinion.security_id).metrics.PARENT_NETPROFIT,1e8) }}</td><td>{{ format(member(opinion.security_id).metrics.NETCASH_OPERATE,1e8) }}</td><td>{{ format(member(opinion.security_id).metrics.pe) }}</td><td>{{ format(member(opinion.security_id).metrics.median_20_turnover,1e8) }}</td></tr></tbody></table></div></section>
      <section class="panel rep-section candidate-pool"><h2>为什么没有选其他公司</h2><p class="condition-note">按业务可比组、核心维度完整度、共同二十日成交额中位数和证券代码排序，最多深研三家。取证预算外的公司不被判断为经营差。</p><details><summary>查看全部 {{ data.coverage.universe_total }} 家公司的去向</summary><div class="candidate-table"><table class="data"><thead><tr><th>公司</th><th>本次去向</th><th>原因与缺项</th></tr></thead><tbody><tr v-for="row in data.members" :key="row.security_id"><th>{{ row.name }}</th><td>{{ data.selected.includes(row.security_id)?'已入选':row.excluded?'已排除':'资料不足或未深研' }}</td><td>{{ row.gaps.join('；') || '在本次排序之后，未取得完整定向深研与审核，不作负面判断' }}</td></tr></tbody></table></div></details></section>
      <section class="panel rep-section"><details><summary>这次研究的范围与局限</summary><p v-for="item in data.limitations" :key="item">{{ item }}</p><p>这是中期候选研究，与下一交易日预测独立；观点已封存，更新将另存。到期收益与投资有效性尚未验证。</p></details></section>
      <section v-if="developer" class="panel rep-section candidate-development"><h2>候选研究开发核验</h2><a class="btn" :href="'/api/quant/decision/runs/'+id+'/export'" target="_blank" rel="noopener noreferrer">导出完整候选与依据</a><details><summary>原始成分、排序、调用与审核</summary><pre>{{ JSON.stringify({universe:data.universe,screening:data.screening_result,members:data.members,calls:state.calls,process:state.process,model_calls:state.model_calls,tokens:state.tokens,elapsed_seconds:state.elapsed_seconds,analysis_ref:data.analysis_ref,review_ref:data.review_ref,candidate_snapshot_ref:data.candidate_snapshot_ref},null,2) }}</pre></details></section>
    </template>
    <details v-if="records.length" class="panel rep-section research-history"><summary>已保存的候选研究 · {{ records.length }} 份</summary><a v-for="row in records" :key="row.run_id" class="prediction-history" :href="'#/candidates/'+row.run_id">{{ row.title }} · {{ new Date(row.created_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}) }}</a></details>
    <p class="condition-note"><a :href="toggle()">{{ developer?'返回用户视图':'开发者入口' }}</a></p>
    <DecisionCitation v-if="citation" :key="citation" :run-id="id" :evidence-id="citation" :developer="developer" @close="citation=null"/>
  </div>
</template>
<style scoped>
.candidate-page .panel{margin-bottom:20px}.candidate-form,.candidate-actions{display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin:20px 0}.candidate-form select{padding:10px;color:var(--text-1);background:var(--bg-base);border:1px solid var(--border);border-radius:6px}.candidate-summary{font-size:18px;line-height:1.9}.candidate-card p{line-height:1.9}.candidate-number{color:var(--accent);padding-right:16px}.candidate-reasons{display:grid;grid-template-columns:1fr 1fr;gap:28px;margin:24px 0}.candidate-card h3{font-size:13px;color:var(--text-2)}.candidate-card b{font-weight:500}.candidate-page details{padding:14px 0;line-height:1.9}.candidate-page summary{cursor:pointer;color:var(--text-2)}.candidate-table{overflow-x:auto;max-width:100%;margin:20px 0}.candidate-table :is(th,td){min-width:120px;vertical-align:top;line-height:1.8}.candidate-citations .prediction-source{background:none;border:0;border-bottom:1px solid var(--accent);color:inherit;font:inherit;font-size:12px;margin:8px 14px 8px 0;cursor:pointer}.candidate-page pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:65vh;overflow:auto}.prediction-history{display:block;padding:12px 0}.candidate-page :is(button,a,summary,select):focus-visible{outline:2px solid var(--accent);outline-offset:4px}@media(max-width:700px){.candidate-reasons{grid-template-columns:1fr;gap:4px}.candidate-summary{font-size:16px}.candidate-card .section-heading{flex-wrap:wrap;gap:10px}.candidate-form{align-items:stretch;flex-direction:column}.candidate-page{min-width:0}}
</style>
